"""Render reviewed questions, timing, reader controls and listening examples."""
from html import escape as e
import json
from pathlib import Path
from site_navigation import project_tabs,experiment_subtabs
from question_pilot_progress import progress_panel
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'research/question-pilot';TN=0;FN=0
def read(name):return json.loads((D/name).read_text()) if (D/name).exists() else None
def clock(t):return f'{int(round(t))//60}:{int(round(t))%60:02d}'
def table(caption,headers,rows):
 global TN;TN+=1
 return '<div class="table-wrap"><table><caption>Table '+str(TN)+'. '+e(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(x))+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def figure(content,caption):
 global FN;FN+=1;return '<figure>'+content+'<figcaption>Figure '+str(FN)+'. '+caption+'</figcaption></figure>'
def histogram(bins,counts,unit,stem):
 maximum=max(counts);bars=''.join('<li><span>'+e(f'{a:g}–{b:g} {unit}')+'</span><span class="bar-space"><span class="bar" style="width:'+str(100*n/maximum)+'%"></span></span><strong>'+str(n)+'</strong></li>' for a,b,n in zip(bins,bins[1:],counts))
 return '<ul class="hist-bars">'+bars+'</ul><p class="small"><a href="../research/question-pilot/figures/'+stem+'.png">Download PNG</a> · <a href="../research/question-pilot/figures/'+stem+'.svg">SVG</a></p>'
def audio_card(c):
 base='../research/question-pilot/'
 return '<article class="listen-card" data-speech="'+str(c['synthetic_speech_playback_start_seconds'])+'" data-end="'+str(c['synthetic_speech_playback_end_seconds'])+'"><h3>'+e(c['meeting']+' · requester '+c['requester']+' · '+clock(c['source_time_seconds']))+'</h3><p class="question">'+e(c['question'])+'</p><p>The original meeting pauses at '+clock(c['source_time_seconds'])+'. Synthetic speech starts '+f"{c['synthetic_speech_playback_start_seconds']:.2f}"+' seconds into this clip.</p><audio controls preload="none" src="'+base+c['public_injected']+'"></audio><p><button class="jump-question" type="button">Play from the question</button> <span class="playback-state" aria-live="polite">Original meeting context</span></p><details><summary>Compare voices and check wording</summary><p>Original requester, separate earlier speech:</p><audio controls preload="none" src="'+base+c['public_reference']+'"></audio><p>Synthetic question alone, after level and room-tone matching:</p><audio controls preload="none" src="'+base+c['public_matched']+'"></audio><p>ASR transcript: “'+e(c['processed_asr']['text'])+'”. Normalized word error rate: '+f"{100*c['processed_asr']['wer']:.1f}%"+'.</p><p>Setting: '+e(c['setting']['id'])+'. Held-out speaker cosine: '+f"{c['speaker_check']['target_cosine']:.3f}"+'. This is a similarity proxy; please judge the voice and acoustics by listening.</p></details></article>'
def main():
 qs=read('questions.json') or [];timing=read('timing.json');gen=read('generation-summary.json');reader=read('reader-review.json');audio=read('audio.json');resources=read('resources.json')
 body='<header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header><div class="container collection-nav">'+experiment_subtabs('ami')+'</div><main id="main"><div class="container"><header class="hero"><span class="eyebrow">Expanded question and audio pilot</span><h1>Useful questions earlier in the conversation</h1><p class="lede">51 new question wordings cover 39 information needs. Thirty-six wordings occur near five to ten minutes. The earlier questions and audio are preserved.</p></header>'+progress_panel()
 body+='<nav class="jump-links" aria-label="On this page"><a href="#method">How it works</a><a href="#generation">Generation</a><a href="#timing">Timing</a><a href="#reader">Reader controls</a><a href="#audio">Listen</a><a href="#questions">Questions</a></nav><section class="section" id="method"><h2>How the questions and audio are made</h2><p>EN2002b is an AMI project meeting about building a meeting browser. ES2002b, IS1000b and TS3003b are AMI role-play meetings about designing a remote control. Danaher call 4344338 and Monro call 4320211 add technical financial discussion. Every request addresses a separate assistant. Earnings-call requests simulate a private aside while listening.</p>'
 stages=[('Cut the history','Manual transcript, speaker labels, roles and a question time','Only speech available before that time'),('Write and review','Earlier transcript or checked fact cards; requester motivation','A natural question and source-checked evaluation reference'),('Test the reader','Question and controlled versions of earlier speech','An answer with citations; reference answers and selected evidence stay hidden'),('Condition the voice','Exact question text and earlier requester speech with its transcript','F5-TTS acoustic features, then a Vocos waveform'),('Match and insert','Synthetic speech; past speech level and room tone','A short recording that pauses, plays the question and resumes'),('Check and listen','Generated speech, question text and disjoint earlier requester speech','ASR wording checks, speaker-similarity proxies and review clips')]
 body+=figure('<div class="pipeline">'+''.join('<div class="module"><strong>'+str(i)+'. '+e(x[0])+'</strong><p><b>Input:</b> '+e(x[1])+'.</p><p><b>Output:</b> '+e(x[2])+'.</p></div>' for i,x in enumerate(stages,1))+'</div>','Six modules and their inputs and outputs. Reader answers are offline quality controls; assistant-answer audio remains deferred.')
 body+='<p><strong>Speaker diarization</strong> identifies who spoke; this pilot uses AMI’s manual speaker labels. <strong>Time alignment</strong> locates those words on the recording clock. <strong>Voice conditioning</strong> guides synthesis with a short requester recording without training new weights. <strong>ASR</strong> transcribes generated speech to check its words.</p><p>AMI question times fall in annotated gaps without cutting a word. Completed transcript excerpts become available after an assumed 0.5-second delay. Earnings timestamps come from automatic alignment and support text controls here; their audio insertion points remain unverified.</p></section>'
 if gen:
  body+='<section class="section" id="generation"><h2>What did the generation pilot produce?</h2><p>The 30B Qwen3 Instruct model produced 78 complete drafts. We retained 15 model wordings and added 36 questions written and source-checked by the report assistant. The model wrote useful ordinary reminders more reliably than questions needing a second source fact. The six strongest source-linked candidates were authored after inspecting the passages.</p><p>The initial run compared ordinary reminders with a connected-fact prompt, which returned no connected questions. We then selected six related source pairs ourselves and tested composition and independent rewriting. A shorter prompt used verified fact cards and three unrelated writing examples. Rewriting receives an actual earlier simple question, without the composition method’s final wording.</p>'
  body+=table('Generation and selection counts. Each call can return up to two drafts; the short prompt returns one. A no-question call explicitly returns no candidate. An unfinished response ends before a complete structured response can be read. Kept wordings satisfy the review criteria below.',['Prompt','Model calls','Complete drafts','No-question calls','Unfinished responses','Kept wordings'],[[r['prompt'],r['calls'],r['drafts'],r['no_question_calls'],r['incomplete_responses'],r['retained']] for r in gen['methods']])
  body+='<p>Review required a plausible request to the separate assistant, source support or an explicitly missing decision, correct requester motivation, and useful earlier-history use. Valid duplicates could be omitted. Retained model question text is unchanged; one requester was corrected, and source or reference-answer corrections are recorded on the cards.</p><p>In the meeting-browser project, several drafts asked the assistant to promise when it would finish the interface, although it only observes the meeting. Other rewrites supplied the requested survey percentage in the question or added a clause that did not change the evidence needed. These do not establish harder history tracking.</p><p>Six authored questions connect separate discussions through a person, a feature or a changed plan. One model question compares two discussions. These seven receive extra evidence controls. We call them <strong>source-linked candidates</strong>: the count describes their intended structure, not proven difficulty. Six simple model questions are paired controls and count as alternative wordings of the same information needs.</p></section>'
 if timing:
  s=timing['wordings'];u=timing['information_needs'];body+='<section class="section" id="timing"><h2>When would the questions be inserted?</h2><p>The mean across all 51 wordings is <strong>'+f"{s['mean_minutes']:.2f} minutes"+'</strong> after the start, or <strong>'+f"{s['mean_percent']:.2f}%"+'</strong> of the conversation. Thirty-six wordings use early checkpoints, whose actual times range from 4:56 to 10:01. Later checkpoints supply longer-context examples.</p><p>We prepared 24 cutoffs: near five, seven-and-a-half and ten minutes, plus a later point, in each conversation. Retained questions use '+str(timing['planned_positions'])+' positions. Choosing a gap can move the target: ES2002b’s nominal ten-minute point is 9:16. Multiple questions at one point are alternatives for separate trials.</p><div class="plot-grid">'+figure(histogram(timing['time_bins_minutes'],timing['time_counts'],'min','question-minutes'),'Elapsed time at insertion. Bars count the 51 wordings, including paired controls.')+figure(histogram(timing['fraction_bins_percent'],timing['fraction_counts'],'%','question-percent'),'Percentage of the complete conversation elapsed, counting wordings. This is the insertion position, not the age of the answer evidence.')+'</div><p>Counting each information need once gives means of '+f"{u['mean_minutes']:.2f} minutes and {u['mean_percent']:.2f}%"+'. The first retained wording represents each need in that calculation.</p>'
  body+=table('Exact timing by conversation. Distinct needs group alternative wordings aimed at the same information. All times use the original recording clock.',['Conversation','Wordings','Distinct needs','First question','Last question','Mean time'],[[r['meeting'],r['wordings'],r['information_needs'],clock(r['earliest_seconds']),clock(r['latest_seconds']),f"{r['mean_minutes']:.2f} min"] for r in timing['per_meeting']]);body+='</section>'
 body+='<section class="section" id="reader"><h2>Does the reader need the earlier context?</h2><p>Qwen3-30B-A3B-Instruct-2507 receives the question and transcript, without proposed answers, selected source lists or generation rationale. These are offline transcript-reader tests, separate from a live speech assistant.</p><ul><li><strong>Full history:</strong> all speech available at the original question time.</li><li><strong>Latest minute:</strong> only the preceding sixty seconds.</li><li><strong>Selected evidence removed:</strong> omit cited passages; other mentions may remain.</li><li><strong>Connected-fact controls:</strong> remove each fact group from the full history, then try each group alone. Repeated mentions and guessing from a single remaining speaker can weaken this test.</li><li><strong>Growing context:</strong> eight early questions with stable targets are tested again at later transcript cutoffs. These offline repetitions measure distraction from accumulating context.</li></ul>'
 if reader:
  body+='<p>'+e(reader['lead'])+'</p>'+table(reader['table_caption'],reader['table_headers'],reader['table_rows'])+''.join('<p>'+e(n)+'</p>' for n in reader.get('notes',[]))
  body+='<details><summary>Representative successes and failures</summary>'+''.join('<h3>'+e(x['question_id'])+'</h3><p>'+e(x['description'])+'</p>' for x in reader.get('examples',[]))+'</details>'
 else:body+='<p class="callout">The 197 reader responses are being reviewed. A parsed response alone does not establish correctness.</p>'
 body+='<p>An empty-history application guard returns missing context before invoking a model. That CPU control is excluded from model accuracy counts.</p></section><section class="section" id="audio"><h2>Listen to requester-matched questions</h2><p>Ten selected AMI questions cover four meetings and eight requester voices. Six use early checkpoints. Each voice has past-only conditioning speech and disjoint earlier comparison speech. F5-TTS and Vocos use three reference and inference settings per question. This tunes inference and conditioning; the weights are unchanged.</p><p>Selection checks wording first, then a held-out speaker embedding: a numerical voice-similarity proxy. Speech is resampled to sixteen kilohertz and matched to the requester’s active speech level, with room tone from a preceding gap. Main clips have zero added equalization and no added reverberation. Please judge the voice and acoustic match by listening.</p><p>The <strong>source clock</strong> follows the original meeting. The <strong>playback clock</strong> includes the inserted question. Main players include eighteen seconds of preceding audio and five seconds of continuation. Original samples on either side are copied exactly. The original participants did not record these synthetic questions.</p>'
 if audio:body+='<p>'+e(audio['lead'])+'</p>'+''.join(audio_card(c) for c in audio['clips'])
 else:body+='<p class="callout">Past-only voice preparation is ready. Synthesis follows reader review; the task list tracks its status.</p>'
 body+='</section><section class="section" id="questions"><h2>Inspect all 51 wordings</h2><p>Each card gives the requester, timing and reason to ask. Expand it for the checked evaluation reference and source IDs. These references are not synthesized assistant replies.</p><div class="filters"><label>Conversation<select id="meeting-filter"><option value="all">All conversations</option>'+''.join('<option>'+e(m)+'</option>' for m in sorted({q['meeting'] for q in qs}))+'</select></label><label>Structure<select id="kind-filter"><option value="all">All structures</option><option value="connected">Source-linked authored</option><option value="comparison">Evidence comparison</option><option value="recall">Ordinary reminder</option><option value="status_unknown">Decision not established</option></select></label><label>Time<select id="time-filter"><option value="all">All checkpoints</option><option value="early">Near 5–10 minutes</option><option value="late">Later</option></select></label><output id="question-count" aria-live="polite"></output></div>'
 labels={'connected':'Source-linked authored','comparison':'Evidence comparison','recall':'Ordinary reminder','status_unknown':'Decision not established'}
 for q in qs:
  body+='<article class="question-card" data-meeting="'+e(q['meeting'])+'" data-kind="'+q['kind']+'" data-time="'+q['cohort']+'"><h3>'+e(q['meeting']+' · '+clock(q['at'])+' · '+f"{q['percent']:.1f}% elapsed")+'</h3><p class="small">'+e(labels[q['kind']]+' · requester '+q['requester']+(' · '+q['role'] if q['role'] else ' · perspective from prior speech'))+'</p><p class="question">'+e(q['question'])+'</p><p>'+e(q['requester_reason'])+'</p><details><summary>Evaluation reference and source review</summary><p>'+e(q['reference_answer'])+'</p><p>'+e(q['review_note'])+'</p><p class="small">'+e('Record: '+q['id']+' · Information need: '+q['intent_id'])+'</p><p class="small">Source excerpts: '+e(', '.join(q['source_ids']))+'</p></details></article>'
 body+='</section><section class="section" id="resources"><h2>Models and resources</h2><p>Text inference uses vLLM, a 49,152-token context, prefix caching and CUDA graphs. Weights and cache share GPU 0. F5-TTS uses its native inference API. Audio checks run Parakeet ASR and then ECAPA sequentially on GPU 0. CPU preparation, mixing and publication use zero GPUs. Maximum experiment GPU concurrency is one.</p>'
 if resources:body+=table('Actual allocation per job. Every job has one GPU; all its components share GPU 0. Each GPU stage starts after its predecessor finishes.',['Job','Stage','GPU type / VRAM','GPU role','GPU hours'],[[r['job'],r['stage'],r['gpu_type'],r['role'],f"{r['gpu_hours']:.4f}"] for r in resources['jobs']])+ '<p>Total allocated GPU time: '+f"{resources['gpu_hours']:.4f}"+' GPU hours, including unsuccessful attempts.</p>'
 body+='</section><footer class="section"><h2>Data and earlier work</h2><p><a href="../research/question-pilot/questions.json">Reviewed questions</a> · <a href="../research/question-pilot/timing.json">Timing statistics</a> · <a href="../research/question-pilot/generation-summary.json">Generation counts and criteria</a> · <a href="../research/question-pilot/progress.json">Task list</a> · <a href="../research/question-pilot/manifest.json">File hashes</a></p><p><a href="question-expansion.html">Earlier 23 retained wordings and literature review</a> · <a href="ami-question-audio.html">Earlier TTS comparison</a>. Their questions and audio assets remain unchanged.</p><p>Sources: <a href="https://groups.inf.ed.ac.uk/ami/corpus/">AMI Meeting Corpus</a> (CC BY 4.0), <a href="https://github.com/huangruizhe/ConEC">ConEC</a> and <a href="https://github.com/revdotcom/speech-datasets">Rev speech datasets</a>. Earnings source transcripts, documents and recordings remain local. New public audio uses AMI only.</p></footer></div></main>'
 css='.pilot-todo li{margin:15px 0}.pilot-todo p{margin:5px 0}li{line-height:1.65}.jump-links,.filters{display:flex;flex-wrap:wrap;gap:14px}.pipeline{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.module,.question-card,.listen-card{border:1px solid #8885;border-radius:12px;padding:18px;margin:14px 0;min-width:0}.plot-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.plot-grid figure{margin:14px 0}.hist-bars{list-style:none;padding:0}.hist-bars li{display:grid;grid-template-columns:110px minmax(0,1fr) 26px;gap:8px;align-items:center;margin:12px 0}.bar-space{height:22px;background:#8882}.bar{display:block;height:100%;background:#537fd0}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{padding:11px;text-align:left;border-bottom:1px solid #8885;vertical-align:top}caption{text-align:left;font-weight:600;padding:12px 0}.filters label{display:grid;gap:7px}select{max-width:100%;padding:9px;font:inherit}audio{display:block;width:100%;margin:12px 0}button{font:inherit;padding:9px 13px;cursor:pointer}.question{font-size:1.12rem;font-weight:600}.small{font-size:.9rem;overflow-wrap:anywhere}details p{overflow-wrap:anywhere}summary{cursor:pointer}.callout{border-left:4px solid #537fd0;padding:12px 16px}.playback-state{display:inline-block;margin:5px}article[hidden]{display:none}@media(max-width:650px){.pipeline,.plot-grid{grid-template-columns:1fr}.module{margin:0}.filters{display:grid;grid-template-columns:1fr}.hist-bars li{grid-template-columns:105px minmax(0,1fr) 24px}.question-card,.listen-card{padding:14px}}'
 js="""function filterQuestions(){let n=0;const m=document.getElementById('meeting-filter').value,k=document.getElementById('kind-filter').value,t=document.getElementById('time-filter').value;document.querySelectorAll('.question-card').forEach(c=>{c.hidden=!((m==='all'||m===c.dataset.meeting)&&(k==='all'||k===c.dataset.kind)&&(t==='all'||t===c.dataset.time));if(!c.hidden)n++});document.getElementById('question-count').textContent=n+' of 51 wordings shown'}document.querySelectorAll('.filters select').forEach(s=>s.addEventListener('change',filterQuestions));filterQuestions();document.querySelectorAll('.listen-card').forEach(c=>{const a=c.querySelector('audio'),state=c.querySelector('.playback-state'),s=+c.dataset.speech,end=+c.dataset.end;c.querySelector('.jump-question').addEventListener('click',async()=>{try{if(a.readyState<1){a.load();await new Promise((ok,fail)=>{a.addEventListener('loadedmetadata',ok,{once:true});a.addEventListener('error',fail,{once:true})})}a.currentTime=Math.max(0,s-.15);await a.play()}catch(err){state.textContent='Playback unavailable; try the audio controls.'}});a.addEventListener('timeupdate',()=>{state.textContent=a.currentTime<s?'Original meeting context':a.currentTime<end?'Synthetic requester question':'Original meeting resumed'})});"""
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="New meeting-assistant questions, early checkpoints, reader controls and requester-matched audio."><title>Question pilot · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css"><style>'+css+'</style></head><body><a class="skip-link" href="#main">Skip to pilot</a>'+body+'<script>'+js+'</script></body></html>\n';(ROOT/'experiments/question-pilot.html').write_text(html);print('Rendered',len(qs),'questions;',len(audio['clips']) if audio else 0,'audio clips.')
if __name__=='__main__':main()
